import { column, defineResource, field } from '@mezielabs/azu'
import Tag from '#models/tag'
import TagPolicy from '#policies/tag_policy'
import { createTagValidator, updateTagValidator } from '#validators/tag'

/**
 * Generated by `node ace make:admin-resource Tag --policy`: the admin
 * resource for Tag.
 *
 * A starting point: edit it freely; Azu never regenerates it. The
 * demo added the navigation group, icon and order.
 */
export default defineResource(Tag, {
  group: 'Catalog',
  icon: 'tag',
  order: 3,
  title: 'name',
  search: ['name', 'slug'],
  policy: TagPolicy,
  validators: { create: createTagValidator, update: updateTagValidator },

  columns: [
    column.text('name').sortable(),
    column.text('slug').sortable(),
    column.datetime('createdAt').sortable().hiddenByDefault(),
  ],

  fields: [field.text('name'), field.text('slug'), field.manyToMany('products').searchable('name')],
})
